\label{stabs11}
Let $\mathbb{F}$ be either $\mathbb{C}$ or $\mathbb{R}$, and let $\mathop{m G}
olimits \subset \mathop{m GL}
olimits_{n}(\mathbb{F})$ with $n=\sum_{j=1}^m n_j$.
For each $j\in \{1,\ldots,m\}$, let $H_j,\mathop{m G}
olimits_j\subset \mathop{m GL}
olimits_{n_j}(\mathbb{F})$, and set $H:= igoplus_{j=1}^m H_j$. Next, let 
 
 egin{equation*}
A= igoplus_{j=1}^{m}A_j^{}, \qquad
R= igoplus_{j=1}^{m}R_j^{},
\end{equation*}
 
where matrices $A_1,\ldots,A_m$ have pairwise disjoint spectra (i.e. $A_j$, $A_k$ have no common eigenvalues for $j
eq k$), and likewise, matrices $R_1,\ldots,R_m$ have pairwise disjoint spectra.
Moreover, suppose exactly one of the following conditions hold:
 egin{enumerate}
\item $\mathop{m G}
olimits=\mathop{m O}
olimits_n(\mathbb{F},H)$, 
$H_j^T=H_j$, $A_j\in \mathop{m Skew}
olimits_{n_j}(\mathbb{F},H_j)$, $R_j\in \mathop{m G}
olimits_j=\mathop{m O}
olimits_{n_j}(\mathbb{F},H_j)$, for all $j$.
\item $\mathop{m G}
olimits=\mathop{m Sp}
olimits_n(\mathbb{F},H)$ with $n$ even, $H_j^T=-H_j$, $A_j\in \mathop{m Ham}
olimits_{n_j}(\mathbb{F},H_j)$, with $n_j$ even, $R_j\in \mathop{m G}
olimits_j=\mathop{m Sp}
olimits_{n_j}(\mathbb{F},H_j)$, for all $j$.
\item $\mathop{m G}
olimits=\mathop{m U}
olimits(n,H)$, $\mathbb{F}=\mathbb{C}$, $H_j^{*}=H_j$, $A_j\in \mathop{m Her}
olimits_{n_j}(H_j)$, $R_j\in\mathop{m G}
olimits_j=\mathop{m U}
olimits (n_j,H_j)$, for all $j$.
\end{enumerate}
Then 
 egin{align*}
                                         
\Sigma_{\mathop{m G}
olimits}(A)=\prod_{j=1}^{m}\Sigma_{\mathop{m G}
olimits_j}(A_j), \qquad \mathop{m C}
olimits_{\mathop{m G}
olimits}(R)=\prod_{j=1}^{m}\mathop{m C}
olimits_{\mathop{m G}
olimits_j}(R_j).
\end{align*}

\label{conj}
Assume $\mathbb{F}$ is either $\mathbb{C}$ or $\mathbb{R}$. 
Let $H,P \in \mathop{m GL}
olimits_{n}(\mathbb{F})$,
                            
$\star\in\{*,T\}$, and
                                      
set $\widetilde{H}:=P^{\star} H P$.
Let $\mathop{m G}
olimits, \widetilde{\mathop{m G}
olimits} \subset \mathop{m GL}
olimits_{n}(\mathbb{F})$ and let $\mathfrak{g}, \widetilde{\mathfrak{g}}$ be vector subspaces of $\mathbb{F}^{n 	imes n}$.
Moreover, suppose exactly one of the following conditions hold:
 
 egin{enumerate}
\item 
$H^T=H$, 
$\star=T$, 
$\mathop{m G}
olimits=\mathop{m O}
olimits_n(\mathbb{F},H)$, $\widetilde{\mathop{m G}
olimits}=\mathop{m O}
olimits_n(\mathbb{F},\widetilde{H})$, $\mathfrak{g}= \mathop{m Skew}
olimits_{n}(\mathbb{F},H)$, $\widetilde{\mathfrak{g}}=\mathop{m Skew}
olimits_n(\mathbb{F},\widetilde{H})$. 
\item 
$H^T=-H$, 
$\star=T$, 
$\mathop{m G}
olimits=\mathop{m Sp}
olimits_n(\mathbb{F},H)$, $\widetilde{\mathop{m G}
olimits}=\mathop{m Sp}
olimits_n(\mathbb{F},\widetilde{H})$, $\mathfrak{g} = \mathop{m Ham}
olimits_{n}(\mathbb{F},H)$, $\widetilde{\mathfrak{g}}=\mathop{m Ham}
olimits_n(\mathbb{F},\widetilde{H})$.
\item 
$H^{*}=H$, $\mathbb{F}=\mathbb{C}$, 
$\star=*$, 
$\mathop{m G}
olimits=\mathop{m U}
olimits(n,H)$, $\widetilde{\mathop{m G}
olimits}=\mathop{m U}
olimits (n,\widetilde{H})$, $\mathfrak{g} = \mathop{m Her}
olimits_{}(n,H)$, $\widetilde{\mathfrak{g}}=\mathop{m Her}
olimits(n,\widetilde{H})$.
\end{enumerate}
 
Then we have
 egin{align*}
&\widetilde{\mathop{m G}
olimits}=P^{-1}\mathop{m G}
olimits P, \qquad \quad \widetilde{\mathfrak{g}}=P^{-1} \mathfrak{g} P,\                                           
&\Sigma_{\widetilde{\mathop{m G}
olimits}}(P^{-1}AP) =  P^{-1} ig( \Sigma_{\mathop{m G}
olimits}(A)  ig) P^{}, \quad \mathop{m C}
olimits_{\widetilde{\mathop{m G}
olimits}}(P^{-1}RP) =P^{-1}  ig(\mathop{m C}
olimits_{\mathop{m G}
olimits}(R) ig)P^{}, \qquad A\in \mathfrak{g}, \,\,R\in \mathop{m G}
olimits.
\end{align*}

\label{exF}
(cf. \cite[Example 3.2]{TSOS}) Let $\star$ stand for either transpose $(\star=T)$ or conjugate transpose $(\star=*)$. Assume $d\in \{0,1\}$ and $1\leq p< t\leq N$ with $\gamma:=\alpha_p-\alpha_t>0$, and let $B_{r}\in \mathop{\rm GL}\nolimits_{m_r}(\mathbb{F})$ satisfy $B_r^{\star}=\varepsilon^{\alpha_r+d-1}B_{r}$ for $r\in \{p,t\}$.
Here $N_{\alpha}^{k}(X)$ denotes an $\alpha\times \alpha$ matrix with $X$ on the $k$-th super-diagonal (the main diago\-nal for $k=0$) and zeros elsewhere, and 
$C(n)
                                  
$ denotes the $n$th Catalan number.
For $0\leq k \leq \alpha_t-1$and $F \in \mathbb{F}^{m_t\times m_p}$ set $\mathcal{V}_{p,t}(F,k)\in \mathbb{T}^{\alpha,\mu}$ (see (\ref{0T0})) whose blocks are given by:
                                                                                                                                    
 
\small
\begin{align}
\label{Hptk}
&              
[\mathcal{V}_{p,t}(F,k)]_{rs}=\left\{
\begin{array}{ll}
\hspace{-2mm}\bigoplus_{j=1}^{\alpha_r}I_{m_r}, & \hspace{-1mm} r=s\\
\hspace{-2mm}0,                        & \hspace{-1mm}  r\neq s 
\end{array}
\right. \hspace{-2mm}, \quad \{r,s\}\not\subset\{p,t\},\qquad\,
 
[\mathcal{V}_{p,t}(F,k)]_{tp}=
N_{\alpha_t}^{k}(F ),\\ 
&
[\mathcal{V}_{p,t}(F,k)]_{rr}=T(I_{m_r},V_1^{r},\ldots,V_{\alpha_r-1}^{r}), \quad r\in \{p,t\},\qquad
[\mathcal{V}_{p,t}(F,k)]_{pt}=
N_{\alpha_t}^{k}\big(-B_{p}^{-1}F^{\star}B_{t}\big),\nonumber
              
\end{align}
 
              
  
\small
\[
\begin{array}{l l}
\hspace{-3mm}\begin{array}{l}
V_{j}^{p}:=\left\{\begin{array}{ll}
\hspace{-2mm}a_{n-1}B_{p}^{-1}(F^{\star}B_{t}FB_{p}^{-1})^{n}B_p^{}, & \hspace{-2mm} j=n(2k+
                  
\gamma)\\
\hspace{-2mm}0,                      & \hspace{-2mm} \textrm{otherwise}
\end{array}
\right.\hspace{-1mm}
\\
             
   
V_{j}^{t}:=\left\{\begin{array}{ll}
\hspace{-2mm} a_{n-1}B_{t}^{-1}(B_{t}FB_{p}^{-1}F^{\star})^{n}B_{t}, & \hspace{-2mm} j=n(2k+
                  
\gamma)\\
\hspace{-2mm} 0,                      & \hspace{-2mm} \textrm{otherwise}
\end{array}
\right.\hspace{-1mm}
          
            
 
\end{array}
&                                               
\hspace{-6.0mm}
a_{n}:=
\left\{
\begin{array}{ll}
\hspace{-2mm} -\frac{1}{2^{2n+1}}C(n), & \hspace{-6.5mm} 
                   
\varepsilon=1 \textrm{ or }\varepsilon=-1,\gamma \textrm{ even}\\
\hspace{-2mm} \frac{1}{2^{2n+1}}(-1)^{\frac{n-1}{2}}C(\frac{n-1}{2}), & \hspace{-2.5mm}
\varepsilon=-1,\gamma,n \textrm{ odd}\\
\hspace{-2mm} 0, &  
\hspace{-2.5mm}\textrm{otherwise},
\end{array}
\right.
\end{array}
\]
\normalsize
For instance, if $N=2$, $\alpha_1=4$, $\alpha_2=2$, $k=1$, $d=0$, 
$B_{1}=B_{2}=I$, $\star=T$, $\varepsilon=-1$, then:
 
\small
\begin{equation*}
             
 
\begin{bmatrix}[cccc|cc]
I_{} & 0 & 0 & -\tfrac{1}{2}F^{T}F  &  0  &  -F^{T} \\        
0   & I_{} & 0   & 0  &  0  &   0\\         
0   & 0   & I_{} & 0    &  0 & 0 \\       
0   & 0   &  0  &  I_{}   & 0 &0 \\       
\hline
0   & 0   & 0 & F                         &  I  & 0  \\       
0   & 0   & 0   & 0              &  0    &   I  \\       
       
                                                                 
\end{bmatrix}.
\end{equation*}
\normalsize

\label{stabw2} 
Assume $\alpha=(\alpha_1,\ldots,\alpha_N)$ with $\alpha_{1}>\ldots >\alpha_{N}$,
$m_1,\ldots,m_N\in \mathbb{N}$ and fix $d\in \{0,1\}$. Set $\mu=(\mu_{1},\ldots,\mu_{N})$ with
$\mu_{r}:=
\left\{
\begin{array}{ll}
\hspace{-2mm}m_r, &  \hspace{-1mm} d+\alpha_r \textrm{ odd}\\
\hspace{-2mm}2m_r, & \hspace{-1mm} d+\alpha_r \textrm{ even}
\end{array}
\right.\hspace{-2mm} $, $n:=\sum_{r=1}^N \alpha_r \mu_{r}$, 
and let $\mathbb{T}^{\alpha,\mu}$ be as in (\ref{0T0}), while $\Gamma_{\alpha_r}$ is as in (\ref{Jblock}).
Next, let $\theta,\vartheta_{r,j}\in \{-1,1\}$, 
with $\bigoplus_{j=1}^{m_r}\vartheta_{r,j}=I_{p_r,q_r}$
($m_r=p_r+q_r$).
Define
 
\begin{align}\label{defMH}
& \mathcal{A}^{}= 
\bigoplus_{r=1}^{N}\big(\bigoplus_{j=1}^{m_r}   A_{r}\big), \,\,\, A_{r}:=
\left\{
\begin{array}{ll}
\hspace{-1mm}J_{\alpha_r}(0)\oplus -(J_{\alpha_r}(0))^T,   &  \hspace{-1mm}  
d + \alpha_r \textrm{ even}\\
\hspace{-1mm}  J_{\alpha_r}(0),      &   \hspace{-1mm} 
d + \alpha_r \textrm{ odd}
\end{array}
\right.\hspace{-2mm}, \quad\,\,
\mathcal{R}=\theta e^{\mathcal{A}}, \\
 \nonumber
            
 
              
H= 
\bigoplus_{r=1}^{N} &
\big( \bigoplus_{j=1}^{m_r} 
H_{r,j}\big),
\,\,\,\, H_{r,j}:=
\left\{
\begin{array}{ll}
\hspace{-1.5mm}               
\begin{bsmallmatrix}
0 & I_{\alpha_r}\\
(-1)^{d} I_{\alpha_r} & 0
\end{bsmallmatrix} ,   &  \hspace{-1.5mm} 
d + \alpha_r \textrm{ even}\\
\hspace{-1.5mm}             
\vartheta_{r,j} \Gamma_{\alpha_r},      &   \hspace{-1.5mm} 
d + \alpha_r \textrm{ odd}
\end{array}
\right.\hspace{-2mm},\quad
\mathop{\rm G}\nolimits= 
\left\{ 
\begin{array}{ll}
\hspace{-1.5mm}               
\mathop{\rm O}\nolimits_{n}(\mathbb{F},H),   &  \hspace{-1.5mm} 
d =0\\
\hspace{-1.5mm}             
\mathop{\rm Sp}\nolimits_{n}(\mathbb{F},H),      &   \hspace{-1.5mm} 
d = 1
\end{array}
\right.\hspace{-2mm}.
 
\end{align}


Then the centralizer of $\mathcal{R}$ and the isotropy group of $\mathcal{A}$ under $\mathop{\rm G}\nolimits$-similarity coincide.
                         
                         
Moreover, there exists a nonsingular matrix $\Psi$ such that:
                                                                                 
 
\begin{align}\label{CSgroup}
\Sigma_{\mathop{\rm G}\nolimits}({\mathcal{A}^{}_{}}) = \Psi^{-1}\mathbb{X} \Psi, \qquad \mathbb{X}:=\mathbb{O} \ltimes \mathbb{V}\subset \mathbb{T}^{\alpha,\mu}.
                                                                                                              
\end{align}
 
\begin{enumerate}
\item
The subgroup $\mathbb{O}$ is the Levi factor of $\mathbb{X}$ and is given by:
                                    
                                       
                  
 
\begin{align*}
                                        
\mathbb{O}=\prod_{r=1}^{N} \big(\prod_{j=1}^{\alpha_r} \mathop{\rm G}\nolimits_{r}\big), \qquad\,\, 
             
G_{r}:= \left\{
\begin{array}{ll}
\hspace{-1mm} 
\mathop{\rm O}\nolimits_{m_r}(\mathbb{F}), & \hspace{-1mm}  d+\alpha_r \textrm{ odd}\\
\hspace{-1mm} 
\mathop{\rm Sp}\nolimits_{2m_r}(\mathbb{F}), & \hspace{-1mm}  d+\alpha_r \textrm{ even}
\end{array}
\right.\hspace{-2mm}.
\end{align*}
 
\item
The unipotent radical $\mathbb{V}\subset \mathbb{X}$
                                       
                                                                                                 
is generated by the matrices $\mathcal{W}$ in (\ref{asZ}) and by the matrices $\mathcal{V}_{p,t}(F,k)$ in
(\ref{Hptk}) for 
$\star=T$, $\varepsilon=-1$ and 
\small
$B_r := \left\{
\begin{array}{ll}
\hspace{-1mm} (-1)^{\alpha_r} I_{p_r,q_r} , & d+\alpha_r \textrm{ odd}\\
\hspace{-1mm} 
        
\begin{bsmallmatrix}
0 & I_{m_r}\\
-I_{m_r} & 0
\end{bsmallmatrix}, & d+\alpha_r \textrm{ even}
\end{array}
\right.\hspace{-2mm}$. 
\normalsize
\end{enumerate}


Moreover, $\mathbb X$ admits an explicit parametrization constructed algorithmically.
                                                   
                                                                                                                             
and it yields its $\mathbb{F}$-dimension:
 
\begin{align*}
\mathop{\rm dim}\nolimits_{\mathbb{F}} (\mathbb{X})
=
\sum_{r=1}^{N}\big(\tfrac{1}{2} \alpha_r \mu_{r}^{2}+\sum_{s=1}^{r-1} \alpha_s \mu_{r} \mu_{s}\big) 
+(-1)^{d-1}\sum_{\alpha_r \textrm{ odd}}\tfrac{1}{2} \mu_{r}.
\end{align*}
\normalsize

\label{stabw1}
For $\alpha=(\alpha_1,\ldots,\alpha_N)$ with $\alpha_{1}>\ldots >\alpha_{N}$, 
$\mu=(m_1,\ldots,m_N)$, set $n:=2\sum_{r=1}^N \alpha_r m_r$, and let $\mathbb{T}^{\alpha,\mu}$ be as in (\ref{0T0}) with $\mathbb{F}$ being $\mathbb{C}$ or $\mathbb{R}$.
Fix $d\in \{0,1\}$, $\lambda\in \mathbb{F}^{}\setminus \{0\}$, $\widetilde{\lambda} \in \mathbb{F}\setminus\{i k\pi\}_{k\in \mathbb{Z}}$, and define
 
\begin{align*}
\mathcal{A}^{}(\lambda)= &
\bigoplus_{r=1}^{N}\Big(\bigoplus_{j=1}^{m_r}\big(J_{\alpha_r}(\lambda)\oplus -(J_{\alpha_r}(\lambda))^T\big)\Big),\qquad \quad
\mathcal{R}(\widetilde{\lambda})=e^{\mathcal{A}(\widetilde{\lambda})},\\
H= &
\bigoplus_{r=1}^{N} \Big( \bigoplus_{j=1}^{m_r} 
\begin{bsmallmatrix}
0 & I_{\alpha_r}\\
 (-1)^{d} I_{\alpha_r} & 0
\end{bsmallmatrix}\Big), \qquad
\mathop{\rm G}\nolimits= 
\left\{
\begin{array}{ll}
\hspace{-1.5mm}               
\mathop{\rm O}\nolimits_{n}(\mathbb{F},H),   &  \hspace{-1.5mm} 
d = 0\\
\hspace{-1.5mm}             
\mathop{\rm Sp}\nolimits_{n}(\mathbb{F},H),      &   \hspace{-1.5mm} 
d = 1
\end{array}
\right.\hspace{-2mm}.
\end{align*}
 
Then the isotropy group $\Sigma_{\mathop{\rm G}\nolimits}\big({\mathcal{A}^{}(\lambda})\big)$ and the centralizer $\mathop{\rm C}\nolimits_{\mathop{\rm G}\nolimits}({\mathcal{R}^{}(\widetilde{\lambda})})$ 
coincide for $\lambda=\widetilde{\lambda}\in \mathbb{F}\setminus\{i k\pi\}_{k\in \mathbb{Z}}$, and for $\lambda\in \mathbb{F}^{}\setminus \{0\}$, $\widetilde{\lambda} \in \mathbb{F}\setminus\{i k\pi\}_{k\in \mathbb{Z}}$ they are conjugate to the group 
\[
\mathbb{X}:=\{\mathcal{X}\oplus (\mathcal{X}^{-1})^{T}\mid \mathcal{X}\in \mathbb{T}^{\alpha,\mu}\}\subset \mathbb{T}^{\alpha,\mu}\oplus \mathbb{T}^{\alpha,\mu};\,\quad
\mathop{\rm dim}\nolimits_{\mathbb{F}}(\mathbb{X})=\sum_{r=1}^{N} m_r\big(\alpha_r m_r+2\sum_{s=1}^{r-1}\alpha_s m_s\big).
\]

\label{stabw1Ri}
For $\alpha=(\alpha_1,\ldots,\alpha_N)$ with $\alpha_{1}>\ldots >\alpha_{N}$, 
$\mu=(m_1,\ldots,m_N)$, set $n:=2\sum_{r=1}^N \alpha_r m_r$, and let $\mathbb{T}^{\alpha,\mu}$ be as in (\ref{0T0}) with $\mathbb{F}=\mathbb{C}$.
Next, let $\vartheta_{r,j}\in \{-1,1\}$, 
with $\bigoplus_{j=1}^{m_r}\vartheta_{r,j}=I_{p_r,q_r}$
($m_r=p_r+q_r$).
Fix $d\in \{0,1\}$, $b>0$ and define
 
\begin{align*}
& 
\mathcal{A}^{}:=\bigoplus_{r=1}^{N}\Big(\bigoplus_{j=1}^{m_r} J_{\alpha_r}^{\mathbb{R}}(0,b)\Big), \qquad
                                      
\mathcal{R}:=e^{\mathcal{A}}, \\
       
                        
& 
H=\bigoplus_{r=1}^{N} \Big( \bigoplus_{j=1}^{m_r}  
\vartheta_{r,j}
\Delta_{\alpha_r,d}
\Big), \qquad
\mathop{\rm G}\nolimits= 
\left\{
\begin{array}{ll}
\hspace{-1.5mm}               
\mathop{\rm O}\nolimits_{n}(\mathbb{R},H),   &  \hspace{-1.5mm} 
d = 0 \\
\hspace{-1.5mm}             
\mathop{\rm Sp}\nolimits_{n}(\mathbb{R},H),      &   \hspace{-1.5mm} 
d = 1
\end{array}
\right.\hspace{-2mm}.
\end{align*}
 
Then 
                    
$\Sigma_{\mathop{\rm G}\nolimits}(\mathcal{A}^{})$ and 
                 
$\mathop{\rm C}\nolimits_{\mathop{\rm G}\nolimits}({\mathcal{R}^{}})$ 
coincide and they are conjugate (over $\mathbb{C}$) to the group 
\[
\mathbb{X}\oplus (\mathbb{X}^{-1})^{T}, \qquad \quad \mathbb{X}:=\mathbb{O} \ltimes \mathbb{V} \subset \mathbb{T}^{\alpha,\mu},
\]
where $\mathbb{O}:=\prod_{r=1}^N \prod_{j=1}^{\alpha_r} U(m_r,B_r)$, and
$\mathbb{V}\subset \mathbb{X}$ is a unipotent normal subgroup, generated by the matrices 
$\mathcal{W}$ in (\ref{asZ}) and by the matrices $\mathcal{V}_{p,t}(F,k)$ in
for $\mathcal{F}=\mathcal{C}$, $\star=*$, $\varepsilon=-1$, 
$B_r=\left\{ 
\begin{array}{ll}
\hspace{-1mm}i^{\alpha_r+d} I_{p_r,q_r}, & \hspace{-1mm} \alpha_r+d \textrm{ odd} \\
\hspace{-1mm}i^{\alpha_r+d-1} I_{p_r,q_r}, & \hspace{-1mm} \alpha_r+d \textrm{ even}  \end{array} \right.
$\hspace{2mm}.


Moreover, $\mathbb X$ admits an explicit parametrization given by an algorithm, 
                                                   
and its $\mathbb{R}$-dimension is
 
\begin{align*}
\mathop{\rm dim}\nolimits_{\mathbb{R}} (\mathbb{X})=\sum_{r=1}^{N}\big(m_r^{2}\alpha_r+2\sum_{s=1}^{r-1}\alpha_s m_r m_s\big).
\end{align*}

\label{stabwU}
For $\alpha=(\alpha_1,\ldots,\alpha_N)$ with $\alpha_{1}>\ldots >\alpha_{N}$, 
$\mu=(m_1,\ldots,m_N)$, set $n:=\sum_{r=1}^N \alpha_r m_r$, and let $\mathbb{T}^{\alpha,\mu}$ be as in (\ref{0T0}) with $\mathbb{F}=\mathbb{C}$.
Fix $\lambda\in \mathbb{C}$, $\vartheta_{r,j}\in \{-1,1\}$ with $\bigoplus_{j=1}^{m_r}\vartheta_{r,j}=I_{p_r,q_r}$,
                                                                                                                                  
and define further
 
\begin{align*}
& 
\mathcal{A}_{}
             
=
\bigoplus_{r=1}^{N} \bigoplus_{j=1}^{m_r} A_{r}, \quad
                
A_r
          
=\left\{
\begin{array}{ll}
\hspace{-1mm}J_{\alpha_r}(\lambda), & \hspace{-1mm}\lambda\in \mathbb{R}, \\
\hspace{-1mm}J_{\alpha_r}(\lambda)\oplus (J_{\alpha_r}(\overline{\lambda})), & \hspace{-1mm} \lambda\in \mathbb{C}\setminus \mathbb{R}
\end{array}
\right.\hspace{-2mm}, \qquad \quad \mathcal{U}
          
:=e^{i\mathcal{A}
          
}\\
& 
H
          
=\bigoplus_{r=1}^{N}\bigoplus_{j=1}^{m_r} H_{r,j}, \,\,
H_{r,j}(\lambda)=\left\{
\begin{array}{ll}
\hspace{-2mm} \vartheta_{r,j}  E_{\alpha_r}, & \hspace{-1mm} \lambda\in \mathbb{R}, \\
\hspace{-2mm} E_{2\alpha_r}, & \hspace{-2mm} \lambda\in \mathbb{C}\setminus \mathbb{R}
\end{array}
\right.\hspace{-2mm}, \quad 
                                                                                                                                             
\mathop{\rm G}\nolimits
          
= \left\{\begin{array}{ll} \hspace{-2mm} \mathop{\rm U}\nolimits(n,H
          
), & \hspace{-1mm} \lambda\in \mathbb{R}\\  \hspace{-2mm} \mathop{\rm U}\nolimits(2n,H
          
), & \hspace{-2mm} \lambda\in \mathbb{C}\setminus \mathbb{R}   \end{array}   \right.\hspace{-2mm}.
\end{align*}
 
Then 
                    
$\Sigma_{\mathop{\rm G}\nolimits
          
}\big(\mathcal{A}^{}
          
\big)$ 
                     
$\mathop{\rm C}\nolimits_{\mathop{\rm G}\nolimits
          
}(\mathcal{U}^{}
          
)$ 
coincide, and they are conjugate to the group 
\[
\mathbb{X}
          
:=\left\{\begin{array}{ll}
\mathbb{O} \ltimes \mathbb{V} \subset \mathbb{T}^{\alpha,\mu}  &   \lambda\in \mathbb{R}\\
\{\mathcal{X}\oplus (\mathcal{X}^{-1})^{*}\mid \mathcal{X}\in \mathbb{T}^{\alpha,\mu}\}\subset \mathbb{T}^{\alpha,\mu}\oplus \mathbb{T}^{\alpha,\mu};\,\quad & \lambda\in \mathbb{C}\setminus \mathbb{R}
\end{array}
\right.,
\]
where $\mathbb{O}:=\prod_{r=1}^{N} \prod_{j=1}^{\alpha_r} U(p_r,q_r)$, and $\mathbb{V}\subset \mathbb{X}$ is a unipotent normal subgroup, generated by matrices 
$\mathcal{W}$ in (\ref{asZ}) and by the matrices $\mathcal{V}_{p,t}(F,k)$ in
(\ref{Hptk}) for $\mathbb{F}=\mathbb{C}$, $\varepsilon=1$, $\star=*$, $B_r=I_{p_r,q_r}$. Moreover, $\mathbb X$ admits an explicit parametrization constructed algorithmically, and
\[
\mathop{\rm dim}\nolimits_{\mathbb{R}}(\mathbb{X}
          
)=
\left\{ \begin{array}{ll}
\sum_{r=1}^{N}\big(\alpha_r m_{r}^{2}+2\sum_{s=1}^{r-1} \alpha_s m_{r} m_{s}\big), & \lambda\in \mathbb{R}\\
2\sum_{r=1}^{N} m_r\big(\alpha_r m_r+2\sum_{s=1}^{r-1}\alpha_s m_s\big), & \lambda\in \mathbb{C}\setminus \mathbb{R}
\end{array}
\right.\hspace{-1mm}.
\]

\label{EqT}
Given $\alpha=(\alpha_1,\ldots,\alpha_N)$ with $\alpha_{1}>\ldots >\alpha_{N}$, $\mu=(m_1,\ldots,m_N)$, $d\in\{0,1\}$, 
and let $\mathcal{B}$ be as in (\ref{BBF}). Then the set of solutions $\mathbb{X}$ of the form (\ref{0T0}) of the equation (\ref{eqFYFIY}) with $\star \in \{T,*\}$, $\varepsilon \in \{-1,1\}$, i.e. $\mathcal{X}=[\mathcal{X}_{rs}]_{r,s=1}^{N}\in \mathbb{X}\subset \mathbb{T}^{\alpha, \mu}$ with
              
\begin{equation*}\label{EqTX}
\mathcal{X}_{rs}=
\left\{
\begin{array}{ll}
\hspace{-1mm}[0\quad \mathcal{T}_{rs}], & \alpha_r<\alpha_s\\
\hspace{-1mm}\begin{bmatrix}
\mathcal{T}_{rs}\\
0
\end{bmatrix}, & \alpha_r>\alpha_s\\
\hspace{-1mm}\mathcal{T}_{rs},& \alpha_r=\alpha_s
\end{array}\right., \qquad 
\begin{array}{l}
\\
                                              
\mathcal{T}_{rs}=T\big(A_0^{rs},\ldots,A_{b_{rs}-1}^{rs}\big),\quad b_{rs}:=\min\{\alpha_s,\alpha_r\},\\
\\
A_j^{rs}\in \mathbb{F}^{m_r\times m_s},\quad A_0^{rr}\in GL_{m_r}(\mathbb{F}),
\end{array}
\end{equation*}
 
satisfies the following properties:
\begin{enumerate}
\item \label{EqTa}
                                                              
The Algorithm~\ref{algo} gives a bijective parametrization of $\mathbb X$: the matrices $A_j^{rs}$ with $r>s$, the matrices $A_0^{rr}$ satisfying
$(A_0^{rr})^{\star} B_rA_0^{rr}=B_r$,
and the matrices $Z_j^r$ satisfying
$Z_j^r=-\varepsilon^{\alpha_r-j+d-1}(Z_j^r)^{\star}$
are freely chosen.
The algorithm then uniquely determines the diagonal entries $A_j^{rr}$ for $j\geq1$ and the remaining upper-diagonal entries $A_j^{rs}$ with $r<s$.
                                                                               
Conversely, every $\mathcal X\in\mathbb X$ is obtained in this way.

\begin{algorithm}
\caption{Calculating $A_j^{rs}$ for $r,s\in \{1,\ldots,N\}$, $j\in \{0,1,\ldots, b_{rs}-1\}$.}\label{algo}
              
               
\begin{algorithmic}
\vspace{1mm}
\State \hspace{-4mm} $\Psi^{krs}_{n}:= \sum_{i=0}^{n}\varepsilon^{i}(A_i^{kr})^{\star} B_k A_{n-i}^{ks}$
                                                                            
for $k,r,s\in \{1,\ldots,N\}$, $n\in \{0,1,\ldots b_{rs}-1\}$, $\star\in \{T,*\}$, $\varepsilon=\pm 1$.
\small
\State \hspace{-4mm} 
$\xi_n^{rs}:=
\sum_{i=1}^{n-1} \varepsilon^{i}(A_i^{rr})^{\star}B_{r}A_{n-i}^{rs}
                                                            
                                                    
+ (A_0^{rr})^{\star}B_{r}A_n^{rs}
+\left\{\begin{array}{ll}
\hspace{-2mm} 0, & \hspace{-3mm} s=r\\
\hspace{-2mm} \varepsilon^{n}(A_n^{rr})^{\star}B_{r}A_0^{rs}, &  \hspace{-3mm} s> r
                                                                                     
                                                                            
\end{array}
\right.
$ for $n\in \{0,1,\ldots b_{rs}-1\}$.
                
\normalsize
\vspace{2mm}
\State \hspace{-4mm} \textbf{1:} $A_0^{rr}$ for $r\in\{1,\ldots,N\}$ is any solution of $B_{r}=(A_0^{rr})^{\star}B_{r}A_0^{rr}$,
\State \hspace{-3mm} \textbf{   } $A_j^{rs}$ for $r,s\in \{1,\ldots,N\}$ with $r>s$, $j\in \{0,\ldots,\alpha_{r}-1\}$ are taken arbitrarily.
                                                                                        
                                                                      
       
\State \hspace{-4mm} \textbf{2:} $Z_j^{r}=-\varepsilon^{\alpha_r -j + d-1} (Z_j^{r})^{\star}\in \mathbb{F}^{m_r\times m_r}$ for $r\in \{1,\ldots,N\}$, $j \in \{1,\ldots, \alpha_r-1\}$ is chosen freely.
\For {$j=0:\alpha_1-1$}
    \If {
		                         
		$ j\in \{1,\ldots,\alpha_r-1\}$}
		                                                                                                      
    \State $A_j^{rr}= A_0^{rr} B_{r}^{-1}\Big(Z_j^{r}-\frac{1}{2}\big(\xi_j^{rr}.
                                                                              
                                                      
    +\sum_{k=1}^{r-1}\Psi_{j-\alpha_k+\alpha_r}^{krr}+\sum_{k=r+1}^{N}\Psi_{j-\alpha_{r}+\alpha_k}^{krr}\big)\Big)$, $r\in \{1,\ldots,N\}$
    \EndIf
    \For {$p=1:N-1$}
        \If {
				                        
				$r+p\leq N$, $j < \alpha_{r+p}$}
        \small
        \State \hspace{-3mm} $A_j^{r(r+p)}=-A_0^{rr} B_{r}^{-1}\Big(
                                                                                  
        \xi_j^{r(r+p)}+\sum_{k=1}^{r-1}\Psi_{j-\alpha_k+\alpha_r}^{kr(r+p)}+ \sum_{k=r+1}^{r+p}\Psi_{j}^{kr(r+p)} 
				$\\
        \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad $
				+\sum_{k=r+p+1}^{N}\Psi_{j-\alpha_{r+p}+\alpha_k}^{kr(r+p)}\Big)$   
\normalsize
        \EndIf
    \EndFor
\EndFor
\State \hspace{-4mm} (We define $\sum_{j=l}^{n}a_j=0$ for $l>n$, and the loop p =1 : N-1 is not performed for $N=1$.)
\end{algorithmic}
\end{algorithm}
 
                
 
 
              
                   
The dimension of $\mathbb{X}$ is given by:
                                                                                                 
is:  
\small
\begin{align}
\label{cdim}
&\mathop{\rm dim}\nolimits_{\mathbb{F}}(\mathbb{X})=\left\{\begin{array}{ll}
\hspace{-1mm}\sum_{r=1}^{N}\big(\tfrac{1}{2}m_r^{2}\alpha_r+\sum_{s=1}^{r-1}\alpha_s m_r m_s\big) +
(-1)^{d-1} \sum_{\alpha_r \textrm{ odd}}\tfrac{1}{2} m_r, & 
              
\star=T, \varepsilon=-1\\
\hspace{-1mm}\sum_{r=1}^{N}\big(\tfrac{1}{2}m_r^{}(m_r-1)\alpha_r+\sum_{s=1}^{r-1}\alpha_s m_r m_s\big), & 
              
\star=T, \varepsilon=1
\end{array} \right.\\
& \mathop{\rm dim}\nolimits_{\mathbb{R}}(\mathbb{X})=\sum_{r=1}^{N}\big(m_r^{2}\alpha_r+2\sum_{s=1}^{r-1}\alpha_s m_r m_s\big)\qquad \textrm{for }\star=*, \mathbb{F}=\mathbb{C}. 
\nonumber
\end{align}
\normalsize
 
\item \label{EqTc}
The solution set $\mathbb{X}$ has a structure of a group, a semidirect product
\[
\mathbb{X}_{}=\mathbb{O}_{}\ltimes \mathbb{V}_{},\qquad \mathbb{O}_{}:=\prod_{r=1}^{N}\big(\prod_{j=1}^{\alpha_r} \mathop{\rm G}\nolimits_r\big), \quad \mathop{\rm G}\nolimits_r:=\left\{
\begin{array}{ll}
\hspace{-1mm}\mathop{\rm O}\nolimits_{m_r}(\mathbb{F},B_r), & \hspace{-1mm} B_r^T=B_r\\
\hspace{-1mm}\mathop{\rm Sp}\nolimits_{m_r}(\mathbb{F},B_r), & \hspace{-1mm} B_r^T=-B_r\\
\hspace{-1mm}\mathop{\rm U}\nolimits_{}(m_r,B_r), & \hspace{-1mm} B_r^{*}=\pm B_r
\end{array}
\right.\hspace{-2mm},
\]
in which $\mathbb{V}_{}\subset \mathbb{T}_{}^{\alpha,\mu}$ is unipotent and each $\mathcal{V}\in \mathbb{V}_{}$ is of the form
$\mathcal{V}=\mathcal{W}\prod_{j=0}^{n}\mathcal{V}_{p_j,t_j}(F_j,k_j)$ (for some $n\leq \sum_{r=1}^{N}\sum_{s=1}^{r-1}\alpha_s$), where  
$\mathcal{W}$ is of the form (\ref{asZ}), and all 
$
\mathcal{V}_{p_j,t_j}(F_j,k_j)
                                     
$
are of the form (\ref{Hptk}).
                                                                                            
\end{enumerate}

(\ref{EqTa}) The proof of the Algorithm \ref{algo} has three steps. First, the symmetry relation (\ref{ETTE}) reduces the equation (\ref{eqFYFIY}) to its upper block-triangular part, and the Toeplitz structure reduces each block equation to its first row. Second, we show that the coefficients $A_j^{r(r+p)}$ with $p\geq 1$ occur linearly with coefficient \((A_0^{rr})^\star B_r\), whereas all other terms depend only on previously determined coefficients. This gives the recursion. 


Since $\varepsilon^{\alpha_r-1}B_{r}^{\star}=\varepsilon^{d}B_{r}$, 
                                                                 
one easily verifies that 
 
\small
\begin{align*}
E_{\alpha_r}(I_{m_r})\big(\bigoplus_{j=1}^{\alpha_r}\varepsilon^{j-1}B_r\big)^{\star}  E_{\alpha_r}(I_{m_r})
=
\varepsilon^{\alpha_r-1} \bigoplus_{j=1}^{\alpha_r}\varepsilon^{j-1}  B_{r}^{\star}
=
\varepsilon^{d} \bigoplus_{j=1}^{\alpha_r}\varepsilon^{j-1}  B_{r},
\end{align*}
\normalsize
 
hence
 
\begin{align}
\label{ETTE}
(\mathcal{F}\mathcal{X}^{\star}\mathcal{F}\mathcal{B} \mathcal{X})^{\star}=\mathcal{X}^{\star}\mathcal{B}^{\star}\mathcal{F}\mathcal{X}\mathcal{F} =
\mathcal{X}^{\star}\mathcal{F}(\mathcal{F}\mathcal{B}^{\star}\mathcal{F})\mathcal{X}\mathcal{F}=
\varepsilon^{d}\mathcal{F}(\mathcal{F}\mathcal{X}^{\star}\mathcal{F}\mathcal{B}\mathcal{X})\mathcal{F},
\end{align}


Thus compare the first rows of the blocks in the upper triangular parts of $\mathcal{F}X^{\star}\mathcal{F}\mathcal{B} X$ and $\mathcal{B}$.  
By simplifying the notation with 
\[\mathcal{Y}:=\mathcal{B}\mathcal{X}, \qquad \widetilde{\mathcal{X}}:=\mathcal{F}X^{\star}\mathcal{F},
\] 
and using the standard $k$th row and column notation $\mathcal{M}_{(k)}$ and $\mathcal{M}^{(k)}$, the equation (\ref{eqFYFIY}) can be written as the following a system of equations:
 
\begin{align}
\label{f1}
                                                     
(\mathcal{B}_{r(r+p)})_{1j}= & \big((\widetilde{\mathcal{X}}\mathcal{Y})_{r(r+p)}\big)_{1j} \qquad \qquad \qquad (1\leq j\leq \alpha_{r+p},\quad 0\leq p \leq N-r)  \nonumber
\\
= & (\widetilde{\mathcal{X}}_{rr})_{(1)}(\mathcal{Y}_{r(r+p)})^{(j)}+\sum_{k=r+1}^{N}(\widetilde{\mathcal{X}}_{rk})_{(1)}(\mathcal{Y}_{k(r+p)})^{(j)}
              
 +\sum_{k=1}^{r-1}(\widetilde{\mathcal{X}}_{rk})_{(1)}(\mathcal{Y}_{k(r+p)})^{(j)}.
                  
           
\end{align}


First, to calculate $A_0^{rr}$ for $r\in \{1,\ldots,N\}$, we observe (\ref{f1}) for $p=0$, $j=1$. Since
              
\[
(\widetilde{\mathcal{X}}_{rk})_{(1)}=\left\{
\begin{array}{ll}
\begin{bsmallmatrix}
(A_0^{kr})^{\star} & * & \ldots & *
\end{bsmallmatrix}, & k\geq r\\
\begin{bsmallmatrix}
0 & * & \ldots & *
\end{bsmallmatrix}, & k<r
\end{array}
\right.,\qquad
(\mathcal{Y}_{kr})^{(1)}=
\left\{
\begin{array}{ll}
\begin{bsmallmatrix}
B_{k}A_0^{kr} \\
0\\
\vdots\\
0
\end{bsmallmatrix}, & k\leq r\\
0, & k>r
\end{array}
\right.,
\]
\vspace{-1mm}
we deduce $\sum_{k=1}^{N}(\widetilde{\mathcal{X}}_{rk})_{(1)}((\mathcal{Y})_{kr})^{(1)}=
(A_0^{rr})^{\star}B_{r}A_0^{rr}$, and it implies:
 
\begin{equation}\label{GABA}
B_{r}=(A_0^{rr})^{\star}B_{r}A_0^{rr}, \qquad r\in \{1,\ldots,N\}.
\end{equation}
To complete the Step 1 of Algorithm \ref{algo}, we arbitrarily set $\mathcal{X}_{rs}$ for $N\geq 2$, $r>s$.


Next, we inductively compute the remaining entries of $\mathcal{X}_{r(r+p)}$ for $0\leq p\leq N-r$. Throughout the following recursive computation, we assume
\[
0\leq j<b_{r(r+p)}=\alpha_{r+p}.
\]
Fix $p\in \{0,\ldots, N-1 \}$, $j\leq \alpha_r-1$, but not $p=j=0$, and solve (\ref{f1}) to get $A_j^{r(r+p)}$ (loops $j=0:\alpha_1-1$, $p=1:N-1$ 
of Algorithm \ref{algo}), assuming that we have already determined $A_{n}^{rs}$ for 
 
       
              
\begin{align}\label{induA1}
&j\geq 1, n\in \{0,\ldots,j-1\}, s\geq r 
\quad\textrm{or}\quad p\geq 1, n=j, r\leq s\leq r+p-1 \\
&\textrm{ or } \quad s\leq r, n\in \{0,\ldots,b_{rs}-1\}, N\geq 2, \qquad (1 \leq r, s\leq N).\nonumber
\end{align}
\normalsize


We have
 
\begin{align*}
\widetilde{\mathcal{X}}_{rk}
=
E_{\alpha_r}(I_{m_r})\mathcal{X}_{kr}^{\star} E_{\alpha_k}(I_{m_k})
&=
                                                         
\left\{
\begin{array}{ll}
\hspace{-1mm}\begin{bsmallmatrix}
\widetilde{\mathcal{T}}_{rk}\\
0
\hspace{-1mm}\end{bsmallmatrix}, 
& \alpha_r >\alpha_k \\
\hspace{-1mm}\begin{bsmallmatrix}
0 & \widetilde{\mathcal{T}}_{rk}
\end{bsmallmatrix}, & \alpha_r<\alpha_k\\
\widetilde{\mathcal{T}}_{rk}, & \alpha_r=\alpha_k
\end{array}
\right.\hspace{-1mm}, \quad
\widetilde{T}_{rk}=
T\big((A_0^{kr})^{\star},\ldots,(A_{b_{kr}-1}^{kr})^{\star}\big),
             
\end{align*}
 
 
\vspace{-3mm}
                      
                                                                                                
 
\begin{align}\label{YSP}
&\mathcal{Y}_{ks} 
=
\left\{
\begin{array}{ll}
\hspace{-1mm}\begin{bsmallmatrix}
\mathcal{S}_{ks}\\
0
\end{bsmallmatrix}, 
& \alpha_k >\alpha_s \\
\hspace{-1mm}\begin{bsmallmatrix}
0 & \mathcal{S}_{ks}
\end{bsmallmatrix}, & \alpha_k<\alpha_s\\
\hspace{-1mm}\mathcal{S}_{ks}, & \alpha_k=\alpha_s
\end{array}
\right. \hspace{-2mm}, \quad  
                  
\mathcal{S}_{ks} 
                                                                                              
=T_{\varepsilon}\big(B_k A_0^{ks},\ldots, B_k A_{b_{ks}-1}^{ks}\big),
\end{align}
 
where $T_{\varepsilon}(A_0,\ldots,A_{\alpha-1}):=[T_{jk}]_{j,k=1}^{\alpha}$, $T_{jk}=0$ for $j>k$, $T_{(j+1)(k+1)}=-T_{jk}$, i.e.
  
\setlength{\arraycolsep}{4.4pt}
\small
\begin{align}\label{AltToep}
T_{\varepsilon} (A_0,\ldots,A_{\alpha-1}):=\begin{bmatrix}
  A_{0} & A_{1}         &  \ldots             & \ldots &    A_{\alpha-1}  \\
0       & \varepsilon A_0 & \varepsilon A_{1}   &  \ldots    & \varepsilon A_{\alpha-2} \\
 \vdots & \ddots            & \varepsilon^2 A_0              & \ddots &   \vdots \\ 
 \vdots &  & \ddots   & \ddots            &  \varepsilon^{\alpha-2}A_1\\
                                                         
                                                                                 
0       & \ldots            &  \ldots &  0      & \varepsilon^{\alpha-1}A_0
\end{bmatrix};
                                  
\end{align}
\normalsize
 
     
for $\varepsilon=-1$ this is an $\alpha$-by-$\alpha$ block \emph{alternating upper triangular Toeplitz} matrix.


To simplify the computations, we set ($k,r,s\in \{1,\ldots,N\}$, $n\in \{0,1,\ldots, b_{rs}-1\}$):
 
\small
\begin{align*}
             
\Psi^{krs}_{n}:=
\left\{
\begin{array}{ll}
\hspace{-1mm} 
\begin{bsmallmatrix}
(A_0^{kr})^{\star} & (A_1^{kr})^{\star} & \ldots & (A_{n}^{rr})^{\star} 
\end{bsmallmatrix}
\begin{bsmallmatrix}
B_k A_{n}^{ks} \\
\varepsilon B_k A_{n-1}^{ks} \\
\vdots \\
                           
\varepsilon^{n}B_k A_{0}^{ks} \\
\end{bsmallmatrix}, & \hspace{-1mm} n\geq 0
\\
\hspace{-1mm} 0, & \hspace{-1mm} n<0
\end{array}
\right.
   
=
  
\left\{
\begin{array}{ll}
\hspace{-1mm}  \sum_{i=0}^{n}\varepsilon^{i}(A_i^{kr})^{\star} B_k A_{n-i}^{ks}, & \hspace{-1mm}n\geq 0\\
\hspace{-1mm} 0, & \hspace{-1mm} n<0
\end{array}
\right.\hspace{-2mm}
           
\end{align*}
\normalsize
 
and by using the fact $B_{r}^{\star}=\varepsilon^{\alpha_r+d-1}B_{r}$ for all $r$, we observe the following:
 
       
\begin{align}\label{simetrija}
(\Psi^{krs}_{n})^{\star}
&
= \sum_{i=0}^{n}\varepsilon^{i}(A_{n-i}^{ks})^{\star} B_k^{\star} A_{i}^{kr} 
= \varepsilon^{\alpha_k+d-1} \sum_{i=0}^{n}\varepsilon^{i}  (A_{n-i}^{ks})^{\star} B_k A_{i}^{kr} \\
& =\varepsilon^{\alpha_k+d-1} \varepsilon^{n}\sum_{i=0}^{n}\varepsilon^{n-i}  (A_{n-i}^{ks})^{\star} B_k A_{i}^{kr} 
                                                                                   
                                                                                                       
   
  
                                                                                             
   
  
                                                                                                         
=\varepsilon^{\alpha_k+d-1+n}\Psi^{ksr}_{n}.\nonumber
                   
          
\end{align}
            
  
Furthermore, we obtain
              
\begin{align}\label{psijr}
(\widetilde{\mathcal{X}}_{rk})_{(1)}(\mathcal{Y}_{k(r+p)})^{(n+1)}
&=
\left\{
\begin{array}{ll}
                                                        
\Psi_{n-\alpha_{r+p}+\alpha_k}^{kr(r+p)}, &  k\geq r+p+1\\
\Psi_{n}^{kr(r+p)},                       &  r+p \geq k\geq r+1, p\geq 1\\
\Psi_{n-\alpha_k+\alpha_r}^{kr(r+p)},     &  k\leq r\\
\end{array}
\right..
\end{align}
 
In particular, for $\xi_j^{r(r+p)}$ defined as in Algorithm \ref{algo}, we deduce:
 
       
\begin{align}
\label{xijrp}
(\widetilde{\mathcal{X}}_{rr})_{(1)}(\mathcal{Y}_{r(r+p)})^{(j+1)}
=\xi_j^{r(r+p)}+
\left\{\begin{array}{ll}
\hspace{-2mm}(A_0^{rr})^{\star}B_{r}A_j^{rr}+ \varepsilon^{j}(A_j^{rr})^{\star}B_{r}A_0^{rr}, &  \hspace{-1mm}
                         
p=0\\
                                                                                                                 
\hspace{-2mm}(A_0^{rr})^{\star}B_{r}A_j^{r(r+p)}, & \hspace{-1mm} p\geq 1
\end{array}
\right.\hspace{-1mm}. 
\end{align}
\normalsize


Next, we have
 
\small
\begin{align*}
\begin{array}{l}
(\widetilde{\mathcal{X}}_{rk})_{(1)}=
\left\{
\begin{array}{ll}
\hspace{-1mm}\begin{bsmallmatrix}
(A_0^{kr})^{\star} & (A_1^{kr})^{\star} & \ldots & (A_{\alpha_{r}-1}^{kr})^{\star}
\end{bsmallmatrix}, & \hspace{-1mm} k\geq r\\
\\
\hspace{-1mm}\begin{bsmallmatrix}
0& \ldots & 0 &(A_0^{kr})^{\star}  & \ldots &(A_{b_{kr}}^{kr})^{\star} 
\end{bsmallmatrix}, & \hspace{-1mm} k<r
\end{array}
\right.\hspace{-1mm},
\\
\\
(\mathcal{Y}_{(r+p)(r+p)})^{(j+1)}=
\begin{bsmallmatrix}
B_{r+p} A_j^{(r+p)(r+p)} \\
\varepsilon B_{r+p} A_{j-1}^{(r+p)(r+p)} \\
\vdots\\
\varepsilon^{j}B_{r+p} A_0^{(r+p)(r+p)}
\end{bsmallmatrix},
\end{array}
       
 
\hspace{-4mm}
(\mathcal{Y}_{k(r+p)})^{(j+1)}=
\left\{\begin{array}{ll}
\hspace{-1mm}\begin{bsmallmatrix}
B_k A_j^{k(r+p)} \\
                        
\vdots\\
\varepsilon^{j}B_k A_0^{k(r+p)}\\
0\\
\vdots\\
0
\end{bsmallmatrix}, & \hspace{-4mm} r+p > k\\
                                     
\hspace{-1mm} \begin{bsmallmatrix}
B_k A_{j-\alpha_{r+p}-\alpha_k}^{k(r+p)} \\
                                              
\vdots\\
\varepsilon^{j-\alpha_{r+p}-\alpha_k} B_k A_0^{k(r+p)}\\
0\\
\vdots\\
0
\end{bsmallmatrix}, & \hspace{-2mm} k> r+p
   
                                 
\end{array}
\right.
\hspace{-2mm}.
\end{align*}
\normalsize
 
Hence, the last two terms in (\ref{f1}) for $j+1$ instead of $j$ ($N\geq r+1\geq 2$) are:
              
 
\begin{align}\label{thjrp}
\Xi (j,r,p):=
& \sum_{k=r+1}^{N}(\widetilde{\mathcal{X}}_{rk})_{(1)}(\mathcal{Y}_{k(r+p)})^{(j+1)}\\
=
&\left\{\begin{array}{ll}
\sum_{k=r+1}^{N}\Psi_{j-\alpha_{r}+\alpha_k}^{krr}, & j\geq 1, p=0\\
\sum_{k=r+1}^{r+p}\Psi_{j}^{kr(r+p)}
+\sum_{k=r+p+1}^{N}\Psi_{j-\alpha_{r+p}+\alpha_k}^{kr(r+p)}, & j\geq 0, p\geq 1.               
                                                          
                              
\end{array}
\right.,\nonumber\\
            
 
              
\label{lajrp}
\Lambda(j,r,p):=
&  \sum_{k=1}^{r-1}(\widetilde{\mathcal{X}}_{rk})_{(1)}(\mathcal{Y}_{k(r+p)})^{(j+1)}=\sum_{k=1}^{r-1}\Psi_{j-\alpha_k+\alpha_r}^{kr(r+p)}.
\end{align}
 
For $j,p\geq 0$ with $j+p\geq 1$ we define
 
\begin{equation}\label{Djrp}
D_j^{r(r+p)}:=\xi_j^{r(r+p)}+\Xi(j,r,p)+\Lambda(j,r,p).
\end{equation}
 
We combine (\ref{f1}) with (\ref{xijrp}), (\ref{thjrp}), (\ref{lajrp}), (\ref{Djrp}) to obtain:
 
\begin{align}
\label{eqATB1}
&(A_0^{rr})^{\star}B_{r}A_j^{r(r+p)}=-D_j^{r(r+p)},\qquad p\geq 1,\\
\label{eqATB2}
&(A_0^{rr})^{\star}B_{r}A_j^{rr}+\varepsilon^{j}(A_j^{rr})^{\star}B_{r}A_0^{rr}=-D_j^{rr}, \qquad j\geq 1\,\,\,\,\, (p=0).
\end{align}
 
Thus the equation for an off-diagonal entry $A_j^{r(r+p)}$ with $p\geq 1$ is linear, while the equation for a diagonal entry $A_j^{rr}$ with $j\geq 1$ has the form $A^\star X+\varepsilon^{\beta} X^\star A=B$.
From (\ref{simetrija}) we get 
                                                           
$\Psi^{krr}_{j-\alpha_r+\alpha_k}=\varepsilon^{\alpha_r-j+d-1}(\Psi^{krr}_{j-\alpha_r+\alpha_k})^{\star}$, which further implies that $\xi_j^{rr}$, $\Xi(j,r,0)$, $\Lambda(j,r,0)$ and $D_j^{rr}$ are of the same structure, e.g., $(D^{rr}_{j})^{\star}=\varepsilon^{\alpha_r-j+d-1}D^{rr}_{j}$.


Since (\ref{GABA}) implies 
$A_0^{rr}B_{r}^{-1}=
((A_0^{rr})^{\star}B_{r})^{-1}$, 
the equation
(\ref{eqATB1}) has the solution $A_j^{r(r+p)}=-A_0^{rr} B_{r}^{-1}D_j^{r(r+p)}$ for $p\geq 1$.
Next, obtain $A_j^{rr}$ by solving (\ref{eqATB2}). 
                                                                                                       
Its solution is $X=(A^{\star})^{-1}(Z+\frac{1}{2}B)$ with 
$Z^{\star}=-\varepsilon^{\beta}Z$, where $A^{\star}=(A_0^{rr})^{\star}B_{r}$, $\beta=\alpha_r-j+d-1$, $B=-D_j^{rr}$, and hence
$(A^{\star})^{-1}=
A_0^{rr}(B_{r})^{-1}$. Thus $Z$ parametrizes precisely the homogeneous solutions of the equation for $A_j^{rr}$, $j\ge1$. Moreover, $D_j^{r(r+p)}$ with $p\geq 1$ depends only on $A_n^{rs}$, with $n,r,s$ satisfying (\ref{induA1}). 


It remains to count the free parameters to obtain the dimension formula 
              
in (\ref{EqTa}). In case $\star=T$, $\varepsilon=-1$, each $A_{0}^{rr}$ contributes $\frac{1}{2}m_r (m_r-1)$, any $A_{j}^{rr}$ for $j\geq 1$ contributes $\frac{1}{2}m_r (m_r+(-1)^{\alpha_r-j+d})$, and any $A_{j}^{rs}$ for $r>s$ gives $m_r m_s$:
 
\small
\begin{align*}
\sum_{r=1}^{N}\sum_{s=1}^{r-1}\alpha_s m_r m_s
+& \hspace{-0.7mm}
\sum_{\alpha_r \textrm{ odd}}\hspace{-2.0mm}\big(
                                                
\tfrac{\alpha_r+\varepsilon^{d-1}}{4}(m_r^2-m_r)+
\tfrac{\alpha_r-\varepsilon^{d-1}}{4}(m_r^2+m_r)\big)\\
+& \hspace{-0.7mm}\sum_{\alpha_r \textrm{ even}}\hspace{-2.5mm}
\tfrac{\alpha_r}{4}\big(
                                                
(m_r^2-m_r)+(m_r^2+m_r)\big).
   
\end{align*}
\normalsize
 
Simplifying this expression yields the stated formula in (\ref{cdim}).
                                                                                                                                                         
The cases $\star=T$, $\varepsilon=1$ and $\star=*$, $\mathbb{F}=\mathbb{C}$ are analogous.
                                                                                                                                                                                                                                                                                     

\vspace{3mm}

\noindent
(\ref{EqTc}) Solutions of the equation (\ref{eqFYFIY}) form a group, since for any 
pair of solutions $\mathcal{X}_1,\mathcal{X}_2$ of (\ref{eqFYFIY}), their product $\mathcal{X}_1\mathcal{X}_2^{-1}$ is a solution as well:
              
 
\begin{align*}
\mathcal{F}(\mathcal{X}_1\mathcal{X}_2^{-1})^{\star}\mathcal{F}\mathcal{B} (\mathcal{X}_1\mathcal{X}_2^{-1})
&=\mathcal{F}(\mathcal{X}_2^{-1})^{\star}\mathcal{F}\big(\mathcal{F}\mathcal{X}_1^{\star}\mathcal{F}\mathcal{B} \mathcal{X}_1\big)\mathcal{X}_2^{-1}
=\mathcal{F}(\mathcal{X}_2^{-1})^{\star}\mathcal{F}\mathcal{B}\mathcal{X}_2^{-1}=\\
