\label{genap}
For a nonsingular matrix $H$, such that either $H^T=H$ or $H^T=-H$ or $H^{*}=H$, respectively, let $\mathcal{A}^{}$ be $H$-skew-symmetric or $H$-Ha\-mil\-to\-ni\-an or $H$-Hermitian normal form.
Denote by $\mathcal{J}(\mathcal{A})$ the Jordan canonical form of $\mathcal{A}$ and let $U$ be a corresponding transition matrix, i.e. $\mathcal{A}=U^{-1} \mathcal{J}(\mathcal{A}) U$. 
Then $Q$ is contained in the isotropy group of $\mathcal{A}$ with respect to $H$-orthogonal, $H$-symplectic, or $H$-unitary similarity, respectively, if and only if $X=UQU^{-1}$ is a solution of the system of equations:
\begin{align}\label{QK2}
                                                                                                                          
\mathcal{J}^{}(\mathcal{A})X= X\mathcal{J}^{}(\mathcal{A}), \quad (U^{-1})^{\star} H U^{-1}=  & X^{\star} \big((U^{-1})^{\star} H U^{-1}\big) X, \,\,\, 
\star:=\left\{ \begin{array}{ll}\hspace{-2mm} T, & \hspace{-2mm} H^{}=\pm H^{T}\\
                             \hspace{-2mm} *, & \hspace{-2mm} H = H^{*}  \end{array}  \right. \hspace{-2mm}.
\end{align}

The isotropy group at $\mathcal{A}$ under $H$-orthogonal or $H$-symplectic or $H$-unitary similarity 
consists of all $H$-orthogonal or $H$-symplectic or $H$-unitary matrices $Q$ satisfying the Sylvester equation: 
\begin{equation}\label{HQQH}
\mathcal{A}^{}Q= Q\mathcal{A}^{},\quad Q^{\star} H Q=H  \qquad \qquad (Q^{-1}\mathcal{A}Q=\mathcal{A}).
\end{equation}
We now transform (\ref{HQQH}) to (\ref{QK2}) by inserting $\mathcal{A}=U^{-1} \mathcal{J}(\mathcal{A}) U$ and $Q=U^{-1}XU$.

\label{resAoXXA} 
Suppose $\mathcal{J}$ is the Jordan canonical form (with direct summands of the form (\ref{Jblock})) and let us consider the following matrix equation:
 
\begin{align}\label{eqJYYJ}
\mathcal{J}X=X\mathcal{J}
\end{align}  
 
\begin{enumerate}[label={\arabic*.},ref={\arabic*},
                            
leftmargin=20pt]
\item \label{resAoXXA1}
Let further $\lambda_1,\ldots,\lambda_n\in \mathbb{C}$ be pairwise distinct eigenvalues of $\mathcal{J}=\bigoplus_{j=1}^{n}\mathcal{J}_j$,
in which $\mathcal{J}_j$ consists of all summands that correspond to the eigenvalue $\lambda_j$.
Then the solution of (\ref{eqJYYJ}) is of the form $X=\bigoplus_{j=1}^{n} X_j$, with $X_j$ a solution of $\mathcal{J}_j X_j=X_j\mathcal{J}_j$.

\item \label{resAoXXA2}
Assume $\mathcal{J}=\bigoplus_{r=1}^{N}\big(\bigoplus_{j=1}^{m_r} J_{\alpha_r}(\lambda)\big)$, $\lambda \in \mathbb{C}$ (i.e. $\mathcal{J}$ has precisely one eigenvalue $\lambda$) and $\alpha_1>\ldots>\alpha_N$. Then the solution of (\ref{eqJYYJ}) is $X=[X_{rs}]_{r,s=1}^{N}$, where every block $X_{rs}$ is further an $m_r$-by-$m$ block matrix with $\alpha_r$-by-$ \alpha_s$ blocks of the form
 
\begin{equation}\label{QTY}
\left\{\begin{array}{ll}
\begin{bmatrix} 
0 & T
\end{bmatrix}, & \alpha_r<\alpha_s \\
\begin{bmatrix}
T\\
0
\end{bmatrix}, & \alpha_r>\alpha_s\\
T, & \alpha_r=\alpha_s
\end{array}
\right.,
\end{equation}
 
with $T$ upper triangular Toeplitz matrix of size $b_{rs}\times b_{rs}$; $b_{rs}:=\min\{\alpha_r,\alpha_s\}$. 
\end{enumerate}

\label{resAoXXAo} 
Assume $\mathcal{J}=\bigoplus_{r=1}^{N}\big(\bigoplus_{j=1}^{m_r} \exp({J_{\alpha_r}(\lambda)})\big)$, $\lambda \in \mathbb{C}$.
Then the solutions $X$ of the equation $\mathcal{J}X=X\mathcal{J}$ coincide with those described in Proposition \ref{resAoXXA} (\ref{resAoXXA2}).

Since $\exp({J_{\alpha}(\lambda)})=e^{\lambda }\exp({J_{\alpha}(0)})
                                                                              
$ and $\exp({J_{\alpha}(0)})=S_{\alpha}J_{\alpha}(1)S_{\alpha}^{-1}$ for some transition matrix $S_{\alpha}$, the equation $\exp({J_{\alpha_r}(\lambda)})Y =Y \exp({J_{\alpha_s}(\lambda)})$ transforms to
 
\begin{align}
\label{eJ0XXeJ0}
&\exp({J_{\alpha_r}(0)})Y =Y \exp({J_{\alpha_s}(0)}),\\
\label{J1XXJ1}
&J_{\alpha_r}(1)\widetilde{Y} =\widetilde{Y} J_{\alpha_s}(1), \qquad \quad \widetilde{Y}=S^{-1}_{\alpha_r}YS_{\alpha_s}.
\end{align}
 
By Proposition \ref{resAoXXA} (\ref{resAoXXA2}) every solution $\widetilde{Y}$ of (\ref{J1XXJ1}) is of the form (\ref{QTY}), 
so the dimension of the solution space of (\ref{J1XXJ1}) (or (\ref{eJ0XXeJ0})) is $b_{rs}=\min\{\alpha_r,\alpha_s\}$. Since upper triangular Toeplitz matrices commute, any matrix of the form (\ref{QTY}) solves (\ref{eJ0XXeJ0}).
Thus these solutions form a $b_{rs}$-dimensional subspace, and hence constitute the whole solution space.

