\label{H2r}
&\mathcal{A}'
=\bigoplus_{r=1}^{N}\Big( \bigoplus_{j=1}^{m_r}  \big( \big(J_{\alpha_r}(\lambda) \oplus J_{\alpha_r}(\overline{\lambda})\big) \oplus -\big(J_{\alpha_r}(\lambda)\oplus J_{\alpha_r}(\overline{\lambda})\big)^T \big)\Big), \quad (\mathcal{A}' = S^{-1}\mathcal{A} S) \\
& S =\bigoplus_{r=1}^{N}\Big( \bigoplus_{j=1}^{m_r} 
\Big(
\big(\Omega_{2,\alpha_r}\oplus \Omega_{2,\alpha_r}\big)
\frac{1}{\sqrt{2}}\big(\begin{bmatrix}
I_{\alpha_r} & iI_{\alpha_r}\\
iI_{\alpha_r} & I_{\alpha_r}
\end{bmatrix}
\oplus
\begin{bmatrix}
I_{\alpha_r} & -iI_{\alpha_r}\\
-iI_{\alpha_r} & I_{\alpha_r}
\end{bmatrix}
\Big)
\Big).
                                                                                                                            
         
       
                           
                                                                
        
      
                        
             
\end{align}
                                               
   
                                                                                  
                    
                           
                                                                             
                     
                    
                           
                     
   
       
   
            
      
                
                               
                             
              
       
                
                                
                              
              
      
                
                    
                           
              
      
                
                               
                             
              
       
                
                                
                              
              
      
  
                
                    
                            
               
   
            
      
   
                                      
   
 
Similarly, as we obtained (\ref{J2F}) from (\ref{JCF1}), we use a suitable permutation matrix to collect together blocks of $\mathcal{A}'$ in (\ref{H2r}), corresponding to eigenvalues $\pm \lambda$ and $\pm \overline{\lambda}$:
\small
\begin{align*}
            
\widetilde{\mathcal{A}}'
= & (\widetilde{\Omega}')^{-1}\mathcal{A}' \widetilde{\Omega}'
=\bigoplus_{r=1}^{N}\Big( \bigoplus_{j=1}^{m_r}  \big( \big(J_{\alpha_r}(\lambda) \oplus -(J_{\alpha_r}(\lambda))^{T} \big)\Big) \oplus \bigoplus_{r=1}^{N}\Big( \bigoplus_{j=1}^{m_r}  \big(J_{\alpha_r}(\overline{\lambda})  \oplus -(J_{\alpha_r}(\overline{\lambda})^{T}\big) \big)\Big),\\
H'
= & (\widetilde{\Omega}')^{T} H \widetilde{\Omega}'
                                                
                                                                               
                                                            
= 
\bigoplus_{r=1}^{N}\bigoplus_{j=1}^{m_r} \begin{bsmallmatrix}
0 & I_{\alpha_r}\\
(-1)^{d}I_{\alpha_r} & 0 
\end{bsmallmatrix} \oplus
\bigoplus_{r=1}^{N}\bigoplus_{j=1}^{m_r} \begin{bsmallmatrix}
0 & I_{\alpha_r}\\
(-1)^{d}I_{\alpha_r} & 0 
\end{bsmallmatrix},\\
          
            
               
&\qquad \widetilde{\Omega}':=  \widetilde{\Omega}_1'\widetilde{\Omega}_2', \qquad \widetilde{\Omega}_1':=\bigoplus_{r=1}^{N}
 \Omega_{2,2m_r}(I_{\alpha_r}),\\ 
                                                                     
             
 
       
                              
&\widetilde{\Omega}_2':=\left[e_1(I_{2m_1\alpha_1})\;e_{3}(I_{2m_2\alpha_2})\;\ldots\;e_{2N-1}(I_{2m_N\alpha_N})\;e_2(I_{2m_1\alpha_1})\;e_{4}(I_{2m_2\alpha_2})\;\ldots\;e_{2N}(I_{2m_N\alpha_N})
\right].
                                         
\end{align*}
\normalsize
 
      
   
                                                                                
                    
                            
                           
                                 
                                           
                   
                          
                          
                                           
                   
                          
                    
   
                                                                        
               
                                
                                                 
                                                                                
                                                             
      
                                                              
                   
                          
                          
                                                              
                   
                          
                   
             


Applying Theorem \ref{stabw1} with (\ref{QPsi}) (the complex case) to $\widetilde{\mathcal{A}}'$, we obtain $H'$-orthogonal/$H'$-symplectic solution $Q'$ of the equation $\widetilde{\mathcal{A}}'Q'=Q' \widetilde{\mathcal{A}}'$:
                                                                                                                                  
 
\begin{align*}
Q'=&Q_1' \oplus Q_2'=  (\Psi^{-1}\mathcal{Y}_1\Psi)\oplus (\Psi^{-1} \mathcal{Y}_2 \Psi), \qquad \Psi:=(I\oplus \mathcal{B}_1)(\Omega^{T}\oplus \Omega^{T})\widetilde{\Omega}^{T}U\\
&\mathcal{Y}_1:=\mathcal{X}_1\oplus (\mathcal{X}^{T}_1)^{-1}, \quad \mathcal{Y}_2 :=\mathcal{X}_2\oplus (\mathcal{X}^{T}_2)^{-1}, \qquad 
\mathcal{X}_1,\mathcal{X}_2\in \mathbb{T}^{\alpha,\mu},
\end{align*}
 
where $U$,$\widetilde{\Omega}$, $\mathcal{B}_1$ are as in (\ref{JCF1}), (\ref{J2F}), (\ref{BK}), respectively, and $\Omega$ is from Lemma \ref{lemaP}.
Moreover, $H$-orthogonal/$H$-symplectic solution $Q=\big(S \widetilde{\Omega}'\big) Q' \big((\widetilde{\Omega}')^{-1} S^{-1} \big)$, of $\mathcal{A}Q=Q\mathcal{A}$,                                                                                            
is real precisely when its real conjugate, via $R^{}\widetilde{\Omega}'$, is real:
 
       
\begin{align}
\label{wQR}
         
(R\widetilde{\Omega}')^{-1} Q (R^{}\widetilde{\Omega}')
= &
\big((\widetilde{\Omega}')^{T} R^{T} S^{} \widetilde{\Omega}'\big) Q'  \big((\widetilde{\Omega}')^{-1} S^{-1} R^{}\widetilde{\Omega}'\big), \qquad 
n:=\sum_{r=1}^{N}2\alpha_r m_r,\\
= & 
\frac{1}{2}
\begin{bsmallmatrix}
I_n & -iZ_{}\\
-iZ_{} & I_n 
\end{bsmallmatrix}  
(Q_1'\oplus Q_2')
\begin{bsmallmatrix}
I_n & iZ_{}\\
iZ_{} & I_n 
\end{bsmallmatrix}
=
\begin{bsmallmatrix}
Q_1+ZQ_2 Z & i(Q_1 Z_{}-ZQ_2)\\
i(Q_2 Z_{}- Z Q_1) & Z Q_1 Z + Q_2
\end{bsmallmatrix},\nonumber
                                                                                                                                   
            
            
   
\end{align}
\begin{align*}
&(\widetilde{\Omega}')^{T}   S^{-1} R \widetilde{\Omega}'
=
\frac{1}{\sqrt{2}}\begin{bsmallmatrix}
I_n & iZ_{}\\
iZ_{} & I_n 
\end{bsmallmatrix}, \,\,
                                                                        
              
             
                   
R:=\bigoplus_{r=1}^{N}\Big(\hspace{-1mm} \bigoplus_{j=1}^{m_r}\big(\Omega_{2,\alpha_r}\oplus \Omega_{2,\alpha_r}\big)
\Big), \,
Z:=\bigoplus_{r=1}^{N}\bigoplus_{k=1}^{m_r} (-I_{\alpha_r}\oplus I_{\alpha_r}).
\end{align*}
 
Furthermore, (\ref{wQR}) is real if and only if $Q_2=Z \overline{Q}_1 Z$. 
                                           
Using $\widetilde{\Omega}$ from (\ref{J2F}), we consider an equivalent equation:
\begin{equation}
\label{q2q1b}
\widetilde{\Omega}^T Q_2 \widetilde{\Omega}=(\widetilde{\Omega}^T Z \widetilde{\Omega})(\widetilde{\Omega}^T \overline{Q}_1 \widetilde{\Omega} ) (\widetilde{\Omega}^T Z \widetilde{\Omega}), \qquad \qquad (\widetilde{\Omega}^T Z \Omega=-I_n\oplus I_n).
\end{equation}
Since
$\widetilde{\Omega}^{T}U\widetilde{\Omega}=
I_n \oplus \bigoplus_{r=1}^{N}\big(\bigoplus_{k=1}^{m_r} \Gamma_{\alpha_r}\big)
=I_n \oplus B_1^T$ with $B_1^TB_1=I_n$ (see (\ref{BK})), we get
\small
\begin{align*}
\Psi\widetilde{\Omega} & = \big((I\oplus \mathcal{B})(\Omega^{T}\oplus \Omega^{T})\widetilde{\Omega}^{T}U\big)\widetilde{\Omega}
=
(\Omega^{T}\oplus \Omega^{T}) \big((\Omega^{}\oplus \Omega^{})(I\oplus \mathcal{B}^{T})(\Omega^{T}\oplus \Omega^{T})\big)(\widetilde{\Omega}^{T}U\widetilde{\Omega})\\
& =  (\Omega^{T}\oplus \Omega^{T})
(I_n \oplus B_1) (I_n \oplus B_1^{T}) 
=\Omega^{T}\oplus \Omega^{T},
\end{align*}
\normalsize
 
therefore, we have:
 
\begin{align*}
\widetilde{\Omega}^T Q_k \widetilde{\Omega}
=  (\Psi' \widetilde{\Omega} )^{-1}  \mathcal{Y}_k (\Psi'\widetilde{\Omega})
                                                                                                                                                                                                                                          
    
                                                                                                                                                                                                                                                                                                                                                                           
                                          
                                                                                 
                                        
= (\Omega^{}\oplus \Omega^{})\mathcal{Y}_k (\Omega^{T}\oplus \Omega^{T}), \qquad k\in \{1,2\}.
\end{align*}
\normalsize
 
                                                                                      
                                                                              
The equation (\ref{q2q1b}) then splits into a system of two (equivalent) equations 
\[
\Omega^{} \mathcal{X}_2 \Omega^{T}= -\Omega^{}  \overline{\mathcal{X}}_1 (-\Omega^{T}) , \qquad 
\Omega  (\mathcal{X}_2^T)^{-1} \Omega^{T}=  \Omega  (\overline{\mathcal{X}}_1^T)^{-1}\Omega^{T}.
\]
It yields $\mathcal{X}_2=\overline{\mathcal{X}}_1$, which is equivalent to the fact that $Q$ is real.

Given a $H$-Hermitian normal form $\mathcal{A}$, we solve $\mathcal{A}Q=Q\mathcal{A}$ with $H$-unitary $Q$.
\begin{enumerate}[label={\bf Case \Roman*.},ref={Case \Roman*},wide=0pt,itemsep=15pt]
\item                 
                                                                                                                    
Suppose
 
\begin{align}
             
\mathcal{A}
=\bigoplus_{r=1}^{N}\Big( \bigoplus_{j=1}^{m_r}  \big( J_{\alpha_r}(\lambda)\oplus J_{\alpha_r}(\overline{\lambda}) \big)\Big),\qquad 
H=\bigoplus_{r=1}^{N}\Big( \bigoplus_{j=1}^{m_r} E_{2\alpha_r} \Big). 
\end{align}


We conjugate $\mathcal{A}$ by an appropriate permutation matrix to collect together blocks corresponding to the same eigenvalue ($\lambda$ or $\overline{\lambda}$).
We use $\widetilde{\Omega}$ from (\ref{J2F}) to get
 
\begin{equation}\label{J2FU}
\widetilde{\mathcal{J}}(\mathcal{A}):=\widetilde{\Omega}^{T}\mathcal{A}\widetilde{\Omega}=
\bigoplus_{r=1}^{N}\big( \bigoplus_{j=1}^{m_r} J_{\alpha_r}(\lambda)\big)\oplus 
\bigoplus_{r=1}^{N}\big( \bigoplus_{j=1}^{m_r}  J_{\alpha_r}(\overline{\lambda})\big), \quad 
\end{equation}


Thus $\mathcal{A}Q=Q\mathcal{A}$ (see (\ref{HQQH})) with $H$-unitary $Q$, transforms to 
                                           
              
\begin{equation}\label{wJQQwJU}
\widetilde{\mathcal{J}}(\mathcal{A})X=X\widetilde{\mathcal{J}}(\mathcal{A}), \qquad X=\widetilde{\Omega}^T Q \widetilde{\Omega},\quad 
\qquad (Q^T H Q=H).
\end{equation}
 
Proposition \ref{resAoXXA} gives the solution $X=X_1\oplus X_2$ of (\ref{wJQQwJ}), where $X_1,X_2$ are $N$-by-$N$ block matrices such that their blocks $(X_1)_{rs}$, $(X_2)_{rs}$ are $m_r$-by-$m_s$ block matrices whose blocks are $\alpha_r$-by-$\times \alpha_s$ rectangular Toeplitz of the form (\ref{QTY}).

\quad
The trick of this proof is to write
 
               
             
                
                  
               
              
                                
                
                 
                
              
             
 
 
\begin{align*}
               
H=D K \qquad
D:=\bigoplus_{r=1}^{N}\Big(\bigoplus_{j=1}^{m_r}  \big(E_{\alpha_r}\oplus E_{\alpha_r} \big)  \Big), \quad 
K: =\bigoplus_{r=1}^{N}\big(\bigoplus_{j=1}^{m_r}  
\begin{bsmallmatrix}
0 & I_{\alpha_r}\\
I_{\alpha_r} & 0 
\end{bsmallmatrix}
 \big).
\end{align*}
 
and then to get the decomposition of $\widetilde{\Omega}^{T}  H  \widetilde{\Omega}$:
 
\begin{align}
\label{BKU}
&\widetilde{\Omega}^{T}  H \widetilde{\Omega}
=(\widetilde{\Omega}^{T} D \widetilde{\Omega})(\widetilde{\Omega}^{T} K \widetilde{\Omega})=B \widetilde{K},\\
B:=\widetilde{\Omega}^{T} D \widetilde{\Omega}
=E \oplus E, \quad & E:=\bigoplus_{r=1}^{N}\big(\bigoplus_{j=1}^{m_r} E_{\alpha_r}  \big), \quad
\widetilde{K}:=\widetilde{\Omega}^{T} V \widetilde{\Omega}  =
\begin{bmatrix}
0 & I_{n}\\
I_{n} & 0 
\end{bmatrix},\,  n:=\sum_{r=1}^{N}\alpha_r m_r.\nonumber
\end{align}
 

In view of (\ref{QK2}) for $U=\widetilde{\Omega}^T$, we then characterize the $H$-unitarity of $Q$ by:
 
              
\begin{align}
               
\label{QTQH2U}
\widetilde{\Omega}^{T} H \widetilde{\Omega} =   &  X^{*} \big(\widetilde{\Omega}^{T}H \widetilde{\Omega}\big) X, \qquad \quad
(Q=\widetilde{\Omega} X \widetilde{\Omega}^T)\nonumber\\
            
 
                                                     
 
              
B \widetilde{K} = &  X^{*}  B \widetilde{K} X \nonumber\\
E \oplus E = & (X_1^{*} \oplus X_2^{*}) ( E \oplus E) (\widetilde{K} (X_1 \oplus X_2) \widetilde{K}^{-1})\\
E \oplus E = & (X_1^{*} \oplus X_2^{*}) ( E \oplus E) (X_2 \oplus X_1)\nonumber\\
E = &  X^{*}_1 E X_2,\qquad \quad \big( E = X^{*}_2 E X_1 \big). \nonumber
\end{align}


By conjugating both hand sides of the last equation of (\ref{QTQH2}) by $\Omega$ from Lemma \ref{lemaP}, recalling $\mathcal{F}=\Omega^{T}E\Omega$, and slightly manipulating it, we deduce
 
\begin{align}\label{ortoD3U}
  \Omega^{T}E \Omega = & (\Omega^{T} X_1\Omega)^{*}(\Omega^{T}E\Omega)(\Omega^{T} X_2\Omega)\\
\mathcal{F}= &  \mathcal{X}^{*}_1\mathcal{F} \mathcal{X}_2 \qquad \qquad (\mathcal{X}_1:=\Omega^{T} X_1\Omega, \quad \mathcal{X}_2:=\Omega^{T} X_2\Omega),\nonumber
\end{align}
  
The form of the solution $X=X_1\oplus X_2$ of (\ref{wJQQwJ}) yields $\mathcal{X}_1, \mathcal{X}_2\in \mathbb{T}^{\alpha,\mu}$ (cf. (\ref{0T0}).
                               
Therefore, 
                      
$Q$
                                
is of the form
 
\begin{align}\label{QPsiU}
&Q=\widetilde{\Omega}(X_1\oplus X_2)\widetilde{\Omega}^{T}
=\Psi^{-1} \big(\mathcal{X}_1\oplus (\mathcal{X}^{*}_1)^{-1}\big)\Psi, \qquad \mathcal{X}_1\in \mathbb{T}^{\alpha,\mu},\\
&\qquad \Psi:=(I\oplus \mathcal{F})\big((\Omega^{T}\oplus \Omega^{T})\widetilde{\Omega}^{T}\big).\nonumber
\end{align}
 

\item           
Let the $H$-Hermitian normal form $\mathcal{A}$ with one eigenvalue $\lambda\in \mathbb{R}$ be:
 
\begin{align}
             
\mathcal{A}
=\bigoplus_{r=1}^{N}\Big( \bigoplus_{j=1}^{m_r}  \big( J_{\alpha_r}(\lambda)\big)\Big),\qquad 
H=\bigoplus_{r=1}^{N}\Big( \bigoplus_{j=1}^{m_r}  
\big( \vartheta_{r,j} E_{\alpha_r} \big) \Big)
\end{align} 


                                                   
By proposition \ref{resAoXXA} (\ref{resAoXXA1}) yields the solution of the equation $\mathcal{A}Q=Q\mathcal{A}$ is of the form $Q=[Q_{rs}]_{r,s=1}^{N}$ with an $\mu_r$-by-$\mu_s$ block matrix $Q_{rs}$ whose blocks are $\alpha_r$-by-$\alpha_s$ rectangular Toeplitz
of the form (\ref{QTY}).
\normalsize


\quad
Next, we write $H=EB$, where $E$ is as in (\ref{BKU}) and $B:=\bigoplus_{r=1}^{N}\big(\bigoplus_{j=1}^{m_r} \vartheta_{r,j} I_{\alpha_r}\big)$, hence $H$-unitarity of $Q$ yields
  
               
               
                                                                               
                                                                                 
             
 
 
                                                                           
 
              
\begin{align}\label{QTQ2cU}
 H =  &   Q^{*}  H  Q\nonumber\\
E B = &  E  Q^{*}(E B) Q\\
B = & ( E  Q^{*} E ) B Q.\nonumber
\end{align}
 
We conjugate (\ref{QTQ2cU}) with $\Omega$ from Lemma \ref{lemaP} and get:
 
\begin{align}\label{ortoD2U}
                                                                                                                                                                                                       
&\mathcal{D} =  \mathcal{F}\mathcal{Q}^{*}\mathcal{F}\mathcal{D}\mathcal{Q},\\
            
 
 
               
             
\mathcal{Q}:=\Omega^{T}Q\Omega, \qquad
&\mathcal{B}:=  
\Omega^{T} B \Omega=\bigoplus_{r=1}^{N} 
\big(
\bigoplus_{j=1}^{\alpha_r}
I_{p_r,q_r}
\big)
              
  
\qquad (\mathcal{F}= \Omega^{T}E\Omega).\nonumber
                                                                                     
\end{align}

\quad
                                                                                                                                                              
Due to a special form of $Q$ (described above), $\mathcal{Q}$ is of the form (\ref{0T0}), thus Lemma \ref{EqT} for $\star=*$, $\varepsilon=1$, $\mathcal{X}=\mathcal{Q}$ and $\mathbb{B}$ as in (\ref{ortoD2U}) provides the solution of (\ref{ortoD2U}).
   
                                                                
   
\end{enumerate}
This completes the proof of the theorem.

\label{Rfw}
                  
       
The reduction of the system of equations (\ref{QK2}) to the block Toeplitz structure is substantially more involved in the present setting than in \cite{TSOC,TSOS}. Although in some cases the procedure leads directly to $\mathbb T^{\alpha,\mu}$, this reduction still requires a substantial amount of work; in the remaining cases, one is led to the block Toeplitz equation of Section~\ref{cereq}.
       
                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                              
In the real case, an additional difficulty is that determining the intersection of the corresponding complex centralizer or isotropy group with the group of real nonsingular matrices is itself a nontrivial step.
